}

.reading-precedence-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin: var(--space-lg) 0 var(--space-xl);
}

.reading-precedence-card {
  background: var(--panel);
  border: 1px solid var(--line);
